begin;
do $$declare a uuid:=gen_random_uuid();d uuid:=gen_random_uuid();o uuid:=gen_random_uuid();period uuid;inc uuid;exp uuid;c uuid;cm uuid;ord uuid;report uuid;key uuid:=gen_random_uuid();r jsonb;again jsonb;v bigint;begin
 if exists(select 1 from public.treasury_entries) then raise exception 'Run this isolated smoke only before real treasury entries exist';end if;
 insert into auth.users(id) values(a),(d);
 insert into public.organizations(id,name,short_name,address,account_reference) values(o,'ROLLBACK FMS AGENCY',o::text,'ROLLBACK ADDRESS','ROLLBACK ACCOUNT');
 insert into public.profiles(auth_user_id,ic_name,title,organization_id,status) values(a,'ROLLBACK Agent','TEST',o,'active'),(d,'ROLLBACK Director','TEST',o,'active');
 insert into public.role_assignments(user_id,role,assigned_by) values(a,'agency_representative',d),(d,'finance_director',d);
 insert into public.permission_grants(user_id,permission,assigned_by,reason) select d,p,d,'ROLLBACK TEST delegation' from unnest(enum_range(null::public.permission_key))p;
 update public.profiles set authority_level='AGENCY_HEAD' where auth_user_id=a;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',d,'aal','aal2','role','authenticated')::text,true);execute 'set local role authenticated';
 r:=public.perform_operation('period.create',null,'{"name":"ROLLBACK TEST PERIOD","start_date":"2026-01-01","end_date":"2026-12-31","basis":"ROLLBACK verified basis"}',gen_random_uuid());period:=(r->>'id')::uuid;
 r:=public.perform_operation('category.create',null,'{"code":"ROLLBACK-INC","name":"ROLLBACK INCOME","kind":"INCOME","source":"ROLLBACK TEST LAW","verified":"true","basis":"ROLLBACK verified basis"}',gen_random_uuid());inc:=(r->>'id')::uuid;
 r:=public.perform_operation('category.create',null,'{"code":"ROLLBACK-EXP","name":"ROLLBACK EXPENSE","kind":"EXPENSE","source":"ROLLBACK TEST LAW","verified":"true","basis":"ROLLBACK verified basis"}',gen_random_uuid());exp:=(r->>'id')::uuid;
 perform public.perform_operation('treasury.opening',null,jsonb_build_object('period_id',period::text,'category_id',inc::text,'amount','1000','confirmation',gen_random_uuid()::text,'counterparty','ROLLBACK TEST','proof','ROLLBACK evidence','basis','ROLLBACK opening basis'),gen_random_uuid());
 perform public.perform_operation('appropriation.set',null,jsonb_build_object('period_id',period::text,'category_id',exp::text,'amount','800','basis','ROLLBACK limit basis'),gen_random_uuid());
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'aal','aal1','role','authenticated')::text,true);
 c:=public.save_case_draft(null,0,'FUNDING_REQUEST','{"agencyName":"ROLLBACK FMS AGENCY","agencyAddress":"ROLLBACK ADDRESS","agencyAccount":"ROLLBACK ACCOUNT","applicantName":"ROLLBACK Agent","applicantTitle":"TEST","phone":"TEST","basis":"ROLLBACK TEST LAW","basisNumber":"TEST-1","categoryCode":"ROLLBACK-EXP","categoryName":"ROLLBACK EXPENSE","amount":"600","purpose":"ROLLBACK TEST","justification":"ROLLBACK TEST","recipient":"ROLLBACK TEST","recipientAccount":"PRIVATE TEST ACCOUNT","paymentPurpose":"ROLLBACK TEST"}');
 perform public.perform_operation('case.submit',c,jsonb_build_object('period_id',period::text,'truth_confirmed','true','basis','ROLLBACK submission'),gen_random_uuid());
 perform set_config('request.jwt.claims',jsonb_build_object('sub',d,'aal','aal2','role','authenticated')::text,true);
 perform public.perform_operation('case.review',c,'{"basis":"ROLLBACK review"}',gen_random_uuid());
 perform public.perform_operation('case.approve',c,'{"amount":"600","basis":"ROLLBACK decision"}',gen_random_uuid());
 select reserved into v from public.treasury_accounts;if v<>0 then raise exception 'decision_created_reserve';end if;
 r:=public.perform_operation('commitment.reserve',c,'{"basis":"ROLLBACK reserve"}',gen_random_uuid());cm:=(r->>'id')::uuid;
 r:=public.perform_operation('order.create',cm,'{"basis":"ROLLBACK order"}',gen_random_uuid());ord:=(r->>'id')::uuid;
 select actual into v from public.treasury_accounts;if v<>1000 then raise exception 'order_changed_balance';end if;
 r:=public.perform_operation('order.execute',ord,'{"basis":"ROLLBACK execution","confirmation":"ROLLBACK UNIQUE PAYMENT","proof":"ROLLBACK payment proof"}',key);
 again:=public.perform_operation('order.execute',ord,'{"basis":"ROLLBACK execution","confirmation":"ROLLBACK UNIQUE PAYMENT","proof":"ROLLBACK payment proof"}',key);
 if r<>again then raise exception 'idempotency_failed';end if;
 select actual into v from public.treasury_accounts;if v<>400 then raise exception 'cash_balance_failed';end if;
 select count(*) into v from public.treasury_entries where kind='EXPENSE';if v<>1 then raise exception 'duplicate_expense';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'aal','aal1','role','authenticated')::text,true);
 perform public.perform_operation('report.utilization_submit',c,'{"amount":"600","returned":"0","proof":"ROLLBACK utilization proof","basis":"ROLLBACK utilization"}',gen_random_uuid());
 perform set_config('request.jwt.claims',jsonb_build_object('sub',d,'aal','aal2','role','authenticated')::text,true);
 perform public.perform_operation('report.utilization_accept',c,'{"basis":"ROLLBACK accepted report"}',gen_random_uuid());perform public.perform_operation('case.close',c,'{"basis":"ROLLBACK close"}',gen_random_uuid());
 r:=public.perform_operation('report.generate',period,'{"basis":"ROLLBACK public report"}',gen_random_uuid());report:=(r->>'id')::uuid;
 if (select snapshot->>'closing' from public.public_report_drafts where id=report)<>'400' then raise exception 'report_balance_failed';end if;
 if (select bbcode from public.public_report_drafts where id=report) like '%PRIVATE TEST ACCOUNT%' then raise exception 'private_data_in_report';end if;
 perform public.perform_operation('report.review',report,'{"basis":"ROLLBACK report review"}',gen_random_uuid());perform public.perform_operation('report.approve',report,'{"basis":"ROLLBACK report approval"}',gen_random_uuid());perform public.perform_operation('report.export',report,'{"basis":"ROLLBACK report export"}',gen_random_uuid());
 execute 'reset role';
end;$$;
rollback;
